export type PipeResult<Fns extends ((...args: any[]) => any)[]> =
	Fns extends [(...args: any[]) => any, ...any[]]
		? ((arg: Parameters<Fns[0]>[0]) => ReturnType<Fns extends [...any[], infer Last extends (...args: any[]) => any] ? Last : never>)
			& { extends: <NewFns extends ((...args: any[]) => any)[]>(...fns: NewFns) => PipeResult<[...Fns, ...NewFns]> }
		: ((arg: any) => any)
			& { extends: <NewFns extends ((...args: any[]) => any)[]>(...fns: NewFns) => PipeResult<NewFns> };

