/** 超过 50 步时的递归兜底（首尾类型推导，中间步骤需注解） */
export function pipe(...fns: ((...args: any[]) => any)[]): PipeResult<typeof fns>;
export function pipe(...fns: Function[]) {
	const run: any = (input: any) => fns.reduce((acc, fn) => fn(acc), input);
	run.extends = (...newFns: Function[]) => pipe(...[...fns, ...newFns] as ((...args: any[]) => any)[]);
	return run;
}

// 异步版本：支持中间类型推导 + .extends()

export type PipeAsyncResult<Fns extends ((...args: any[]) => any)[]> =
	Fns extends [(...args: any[]) => any, ...any[]]
		? ((arg: Parameters<Fns[0]>[0]) => Promise<ReturnType<Fns extends [...any[], infer Last extends (...args: any[]) => any] ? Last : never>>)
			& { extends: <NewFns extends ((...args: any[]) => any)[]>(...fns: NewFns) => PipeAsyncResult<[...Fns, ...NewFns]> }
		: ((arg: any) => Promise<any>)
			& { extends: <NewFns extends ((...args: any[]) => any)[]>(...fns: NewFns) => PipeAsyncResult<NewFns> };

