/** 超过 50 步时的递归兜底 */
export function pipeAsync(...fns: ((...args: any[]) => any)[]): PipeAsyncResult<typeof fns>;
export function pipeAsync(...fns: Function[]) {
	const run: any = async (input: any) => {
		let value = input;
		for (const fn of fns) {
			value = await fn(value);
		}
		return value;
	};
	run.extends = (...newFns: Function[]) => pipeAsync(...[...fns, ...newFns] as ((...args: any[]) => any)[]);
	return run;
}
